#!/bin/bash
# Print the three most frequent IPs from access.log, ties broken by first appearance.
awk '
{
    ip = $1
    if (!(ip in count)) first[ip] = ++n
    count[ip]++
}
END {
    # Bucket by count (max 10^9 IPs -> at most 10^9 buckets, but counts are small in practice).
    for (ip in count) {
        c = count[ip]
        bucket[c] = (c in bucket) ? bucket[c] SUBSEP ip : ip
    }
    for (rank = 1; rank <= 3; rank++) {
        # Find the largest count that still has IPs left to output.
        for (c = maxc; c >= 1; c--) {
            if (c in bucket) {
                # Split bucket: IPs are ordered by first appearance thanks to awk string iteration? No.
                # We store them in first-appearance order explicitly, so splitting preserves order.
                split(bucket[c], arr, SUBSEP)
                if (rank == 1 || (rank > 1 && prev_ip != "")) {
                    # We may have consumed some of this bucket on a previous rank? A bucket is
                    # only used for one count value, and we take at most one IP per rank overall,
                    # but multiple ranks could share the same count. Track consumption per bucket.
                }
                idx = (c in taken) ? taken[c] + 1 : 1
                if (idx <= arr_count(c)) {
                    print arr[idx]
                    taken[c] = idx
                    break
                }
            }
        }
        # Record maxc lazily
        if (!(c in maxc_seen)) maxc_seen[c] = 1
    }
}
function arr_count(c,   i, tmp) { tmp = bucket[c]; return split(tmp, arr, SUBSEP) }
' access.log

#!/bin/bash
# Print the three most frequent IPs from access.log, most frequent first,
# breaking ties by first appearance in the log.
awk '
{
    ip = $1
    if (!(ip in count)) order[++n] = ip   # record first-appearance order
    count[ip]++
}
END {
    for (rank = 1; rank <= 3; rank++) {
        best = ""; bestcount = 0
        for (i = 1; i <= n; i++) {
            ip = order[i]
            if (chosen[ip]) continue
            if (count[ip] > bestcount) {
                bestcount = count[ip]
                best = ip
            }
        }
        if (best == "") break
        chosen[best] = 1
        print best
    }
}
' access.log
